    private static readonly FrozenDictionary<int, (int Regular, int Bold)> Advances = Codes
        .Select((code, index) => (code, index))
        .ToFrozenDictionary(entry => entry.code, entry => (Regular[entry.index], Bold[entry.index]));

    public static double Width(string text, double size, bool bold)
    {
        var units = 0;
        foreach (var rune in text.EnumerateRunes())
        {
            units += Advances.TryGetValue(rune.Value, out var advance) && advance.Regular >= 0
                ? bold ? advance.Bold : advance.Regular
                : bold ? Bold[33] : Regular[33];
        }

        return units * size / UnitsPerEm;
    }

    public static double Height(double size) => size * 1.21;
